[tool_call Write] {"file_path":"consumer_lifecycle.py","content":""""One complete REST Proxy v2 consumer session: create -> subscribe ->
fetch/handle/commit -> delete, per docs/contract.json.

Every proxy response is validated before the step counts as done; the
transport surfaces 3xx without following them, and any redirect here means
the session aborts (REDIRECT_BLOCKED). The returned base_uri is only used
when its origin equals the configured proxy origin — otherwise nothing,
credentials included, is sent to it and cleanup goes through the configured
origin. Once the instance exists it is deleted exactly once, best-effort:
cleanup failures never escape, they only leave result.deleted False.
"""

import copy
import urllib.parse

from restproxy import RestProxyError, V2, V2_JSON_EMBEDDED, origin_of

COMPLETED = "COMPLETED"
HANDLER_ERROR = "HANDLER_ERROR"
CANCELLED = "CANCELLED"
PROXY_ERROR = "PROXY_ERROR"

REDIRECT_BLOCKED = "REDIRECT_BLOCKED"
UNTRUSTED_BASE_URI = "UNTRUSTED_BASE_URI"
INVALID_CREATE_RESPONSE = "INVALID_CREATE_RESPONSE"
INVALID_RECORDS_RESPONSE = "INVALID_RECORDS_RESPONSE"


class SessionResult:
    def __init__(self):
        self.outcome = None
        self.failure = None
        self.batches = []
        self.committed = {}
        self.deleted = False

    def __repr__(self):
        return (f"SessionResult(outcome={self.outcome!r}, "
                f"failure={self.failure!r}, batches={len(self.batches)}, "
                f"committed={self.committed!r}, deleted={self.deleted!r})")


class _Abort(Exception):
    """Internal: stop the session with a fixed outcome/failure."""

    def __init__(self, outcome, failure=None):
        super().__init__(failure)
        self.outcome = outcome
        self.failure = failure


def _segment(value):
    """Encode one value as a single RFC 3986 path segment."""
    return urllib.parse.quote(str(value), safe="")


def _succeeded(response):
    return 200 <= response.status < 300


def _require_success(response, step):
    if _succeeded(response):
        return
    if 300 <= response.status < 400:
        raise _Abort(PROXY_ERROR, REDIRECT_BLOCKED)
    raise _Abort(PROXY_ERROR, f"HTTP {response.status} on {step}")


def _last_offsets(records):
    """Highest offset per (topic, partition), in sorted key order."""
    latest = {}
    for rec in records:
        key = (rec["topic"], rec["partition"])
        offset = rec["offset"]
        if key not in latest or offset > latest[key]:
            latest[key] = offset
    return dict(sorted(latest.items()))


def _valid_batch(records):
    if not isinstance(records, list):
        return False
    for rec in records:
        if not isinstance(rec, dict):
            return False
        if not isinstance(rec.get("topic"), str):
            return False
        if not isinstance(rec.get("partition"), int):
            return False
        if not isinstance(rec.get("offset"), int):
            return False
    return True


def run_session(transport, group, instance_name, topics, handler, *,
                max_batches, timeout_ms=1000, max_bytes=65536,
                cancelled=None):
    result = SessionResult()
    cleanup = {"created": False, "url": None}
    try:
        _drive(transport, group, instance_name, topics, handler,
               max_batches, timeout_ms, max_bytes, cancelled,
               result, cleanup)
        result.outcome = COMPLETED
    except _Abort as stop:
        result.outcome = stop.outcome
        result.failure = stop.failure
    except RestProxyError as err:
        result.outcome = PROXY_ERROR
        result.failure = str(err)
    except OSError as err:
        result.outcome = PROXY_ERROR
        result.failure = f"{err.__class__.__name__}: {err}"
    finally:
        if cleanup["created"]:
            result.deleted = _delete_instance(transport, cleanup["url"])
    return result


def _drive(transport, group, instance_name, topics, handler,
           max_batches, timeout_ms, max_bytes, cancelled, result, cleanup):
    create_resp = transport.request(
        "POST", f"/consumers/{_segment(group)}",
        body={"name": instance_name,
              "format": "json",
              "auto.offset.reset": "earliest",
              "auto.commit.enable": "false"})
    # A redirected or otherwise unsuccessful create never made an instance,
    # so it must abort before the cleanup obligation exists.
    _require_success(create_resp, "create")

    cleanup["created"] = True
    body = create_resp.body if isinstance(create_resp.body, dict) else {}
    instance_id = body.get("instance_id")
    if not isinstance(instance_id, str) or not instance_id:
        instance_id = instance_name
    # Configured-origin fallback route; both identifiers stay single
    # path segments no matter what characters they contain.
    cleanup["url"] = (f"/consumers/{_segment(group)}"
                      f"/instances/{_segment(instance_id)}")

    base_uri = body.get("base_uri")
    if not isinstance(base_uri, str) or not base_uri:
        raise _Abort(PROXY_ERROR, INVALID_CREATE_RESPONSE)
    try:
        base_origin = origin_of(base_uri)
    except ValueError:
        base_origin = None
    if base_origin != transport.origin:
        raise _Abort(PROXY_ERROR, UNTRUSTED_BASE_URI)
    # Trusted: instance affinity means every further request, cleanup
    # included, uses the proxy-chosen base_uri verbatim.
    cleanup["url"] = base_uri

    sub_resp = transport.request("POST", base_uri + "/subscription",
                                 body={"topics": list(topics)})
    _require_success(sub_resp, "subscribe")

    records_url = (f"{base_uri}/records"
                   f"?timeout={int(timeout_ms)}&max_bytes={int(max_bytes)}")
    for _ in range(max_batches):
        if cancelled is not None and cancelled():
            raise _Abort(CANCELLED)

        fetch_resp = transport.request("GET", records_url,
                                       accept=V2_JSON_EMBEDDED)
        _require_success(fetch_resp, "fetch")
        records = fetch_resp.body
        if not _valid_batch(records):
            raise _Abort(PROXY_ERROR, INVALID_RECORDS_RESPONSE)
        if not records:
            return  # caught up -> COMPLETED

        # The handler owns `records`; the session keeps an isolated copy
        # so mutations cannot alter the audit trail or the commit body.
        snapshot = copy.deepcopy(records)
        result.batches.append(snapshot)
        offsets = _last_offsets(snapshot)
        try:
            handler(records)
        except Exception as exc:
            raise _Abort(HANDLER_ERROR, str(exc)) from None

        commit_resp = transport.request(
            "POST", base_uri + "/offsets",
            body={"offsets": [{"topic": t, "partition": p, "offset": o}
                              for (t, p), o in offsets.items()]})
        _require_success(commit_resp, "commit")
        result.committed.update(offsets)


def _delete_instance(transport, url):
    """Best-effort DELETE; True only on a confirmed 2xx."""
    try:
        resp = transport.request("DELETE", url)
    except Exception:
        return False
    return _succeeded(resp)
